/**
 * Link-preview images (Open Graph), 1200 × 630, per page and language, keyed by the address
 * without its language prefix ('' is the Home page). Pages without an entry use the Home image.
 *
 * Generated by scripts/og-images.mjs from src/data: run `npm run og` after changing a page's
 * title or lead, a product, or the contact details, then commit public/og and this file.
 * ogImageSources records what each image was made from; `node scripts/og/check.mjs` compares it
 * with src/data (no browser needed) and fails when an image is out of date.
 * Do not edit by hand.
 */
export interface OgImage {
  /** Address under public/, with a content hash so platforms fetch a changed image again. */
  src: string;
  width: number;
  height: number;
  type: 'image/png' | 'image/jpeg';
  /** What the image shows (og:image:alt, twitter:image:alt). */
  alt: string;
}

